//! The `mtls`-gated tests exercise the real `reqwest::Identity` build path
//! (`RestStream::new` → `apply_client_tls`) from a self-signed PEM pair and a
//! PKCS#12 bundle. A full mTLS *handshake* needs a client-auth-requiring TLS
//! server, which is out of scope here; these assert that a valid identity is
//! accepted and an invalid one is rejected with a typed error that never echoes
//! key material. The non-`mtls` test asserts a `tls:` block fails loudly on a
//! build without the feature.

use faucet_source_rest::{RestStream, RestStreamConfig, TlsClientConfig};

const CERT: &str = include_str!("fixtures/mtls/cert.pem");
const KEY: &str = include_str!("fixtures/mtls/key.pem");

#[cfg(feature = "mtls")]
#[test]
fn pem_identity_builds_a_client() {
    let cfg = RestStreamConfig::new("https://example.test", "/x").tls(TlsClientConfig {
        client_cert: Some(CERT.to_string()),
        client_key: Some(KEY.to_string()),
        ..Default::default()
    });
    assert!(
        RestStream::new(cfg).is_ok(),
        "a valid PEM cert/key pair must build the client"
    );
}

#[cfg(feature = "mtls")]
#[test]
fn pem_identity_with_min_version_builds() {
    let cfg = RestStreamConfig::new("https://example.test", "/x").tls(TlsClientConfig {
        client_cert: Some(CERT.to_string()),
        client_key: Some(KEY.to_string()),
        min_version: Some("1.2".into()),
        ..Default::default()
    });
    assert!(RestStream::new(cfg).is_ok());
}

#[cfg(feature = "mtls")]
#[test]
fn invalid_pem_is_rejected_without_leaking_key() {
    let cfg = RestStreamConfig::new("https://example.test", "/x").tls(TlsClientConfig {
        client_cert: Some("-----BEGIN CERTIFICATE-----\nnope\n-----END CERTIFICATE-----".into()),
        client_key: Some("SUPERSECRETKEYMATERIAL".into()),
        ..Default::default()
    });
    let err = RestStream::new(cfg).expect_err("malformed PEM must error");
    let msg = err.to_string();
    assert!(msg.contains("tls:"), "error should be a tls config error: {msg}");
    assert!(
        !msg.contains("SUPERSECRETKEYMATERIAL"),
        "key material must never appear in the error: {msg}"
    );
}

#[cfg(feature = "mtls")]
#[test]
fn pkcs12_identity_builds_a_client() {
    let p12 = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/mtls/identity.p12");
    let cfg = RestStreamConfig::new("https://example.test", "/x").tls(TlsClientConfig {
        client_identity_pkcs12: Some(p12.to_string()),
        pkcs12_password: Some("changeit".into()),
        ..Default::default()
    });
    assert!(
        RestStream::new(cfg).is_ok(),
        "a valid PKCS#12 identity must build the client"
    );
}

#[cfg(feature = "mtls")]
#[test]
fn missing_pkcs12_file_errors() {
    let cfg = RestStreamConfig::new("https://example.test", "/x").tls(TlsClientConfig {
        client_identity_pkcs12: Some("/no/such/identity.p12".into()),
        pkcs12_password: Some("x".into()),
        ..Default::default()
    });
    assert!(RestStream::new(cfg).is_err());
}

#[cfg(feature = "mtls")]
#[test]
fn invalid_tls_shape_is_rejected_before_build() {
    // Both PEM and PKCS#12 set → validation error (not a build error).
    let cfg = RestStreamConfig::new("https://example.test", "/x").tls(TlsClientConfig {
        client_cert: Some(CERT.to_string()),
        client_key: Some(KEY.to_string()),
        client_identity_pkcs12: Some("/path/id.p12".into()),
        ..Default::default()
    });
    assert!(RestStream::new(cfg).is_err());
}

#[cfg(not(feature = "mtls"))]
#[test]
fn tls_config_without_mtls_feature_errors() {
    let cfg = RestStreamConfig::new("https://example.test", "/x").tls(TlsClientConfig {
        client_cert: Some(CERT.to_string()),
        client_key: Some(KEY.to_string()),
        ..Default::default()
    });
    let err = RestStream::new(cfg).expect_err("tls without the mtls feature must error");
    assert!(
        err.to_string().contains("mtls"),
        "error should mention the mtls feature: {err}"
    );
}

