//! Configuration for the authenticated HTTP file source.

use faucet_core::AuthSpec;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

/// File format of the downloaded blob.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema, Default)]
#[serde(rename_all = "snake_case")]
pub enum FileFormat {
    /// Infer from the URL extension (`.xlsx`/`.xls` → Excel, else CSV). Default.
    #[default]
    Auto,
    /// Comma/delimiter-separated text.
    Csv,
    /// Excel workbook (`.xlsx`/`.xls`). Requires the `excel` crate feature.
    Excel,
}

/// Authentication for the file download. Inline `{ type, config }` or a
/// `{ ref: <name> }` pointer to a shared provider — the same shape every other
/// HTTP connector uses, so a OneDrive/Graph token minted by an `oauth2_refresh`
/// provider can be shared via `auth: { ref }`.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(tag = "type", content = "config", rename_all = "snake_case")]
pub enum HttpFileAuth {
    /// No authentication.
    None,
    /// `Authorization: Bearer <token>`.
    Bearer { token: String },
    /// HTTP Basic credentials.
    Basic { username: String, password: String },
    /// An API key in a named header (e.g. `X-Api-Key`).
    ApiKey { header: String, value: String },
    /// Arbitrary headers attached to the request.
    Custom { headers: HashMap<String, String> },
}

impl Default for HttpFileAuth {
    fn default() -> Self {
        HttpFileAuth::None
    }
}

fn default_delimiter() -> u8 {
    b','
}
fn default_has_headers() -> bool {
    true
}
fn default_header_row() -> usize {
    0
}
fn default_batch_size() -> usize {
    faucet_core::DEFAULT_BATCH_SIZE
}

/// Configuration for [`HttpFileSource`](crate::HttpFileSource).
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct HttpFileSourceConfig {
    /// URL of the file to download (e.g. a Microsoft Graph
    /// `/drive/items/{id}/content` endpoint). Supports `{key}` context
    /// substitution.
    pub url: String,

    /// Authentication for the request. Inline or `{ ref: <name> }`.
    #[serde(default)]
    pub auth: AuthSpec<HttpFileAuth>,

    /// File format. `auto` (default) infers from the URL extension.
    #[serde(default)]
    pub format: FileFormat,

    // ── CSV options ─────────────────────────────────────────────────────────
    /// CSV field delimiter (default `,`).
    #[serde(default = "default_delimiter")]
    pub delimiter: u8,
    /// Whether the first CSV row is a header row supplying field names
    /// (default `true`). When `false`, fields are named `column_0`, `column_1`, …
    #[serde(default = "default_has_headers")]
    pub has_headers: bool,

    // ── Excel options ───────────────────────────────────────────────────────
    /// Worksheet to read: a sheet name, or a 0-based index as a string. When
    /// omitted, the first worksheet is used.
    #[serde(default)]
    pub sheet: Option<String>,
    /// 0-based row index of the Excel header row (default `0`). Rows above it
    /// are skipped; the header row supplies field names.
    #[serde(default = "default_header_row")]
    pub header_row: usize,

    // ── Streaming / reliability ─────────────────────────────────────────────
    /// Records per emitted page (default [`DEFAULT_BATCH_SIZE`](faucet_core::DEFAULT_BATCH_SIZE)).
    /// `0` drains the whole file into a single page.
    #[serde(default = "default_batch_size")]
    pub batch_size: usize,
    /// Per-request HTTP timeout in seconds (default `60`).
    #[serde(default)]
    pub timeout_secs: Option<u64>,
}

impl HttpFileSourceConfig {
    /// Create a config with the required URL and defaults.
    pub fn new(url: impl Into<String>) -> Self {
        Self {
            url: url.into(),
            auth: AuthSpec::Inline(HttpFileAuth::None),
            format: FileFormat::Auto,
            delimiter: b',',
            has_headers: true,
            sheet: None,
            header_row: 0,
            batch_size: faucet_core::DEFAULT_BATCH_SIZE,
            timeout_secs: None,
        }
    }

    /// Resolve `format: auto` against the URL extension.
    pub fn resolved_format(&self) -> FileFormat {
        match self.format {
            FileFormat::Auto => {
                let lower = self.url.split('?').next().unwrap_or(&self.url).to_lowercase();
                if lower.ends_with(".xlsx") || lower.ends_with(".xls") {
                    FileFormat::Excel
                } else {
                    FileFormat::Csv
                }
            }
            other => other,
        }
    }

    /// Validate the config: non-empty URL and a sane `batch_size`.
    pub fn validate(&self) -> Result<(), faucet_core::FaucetError> {
        if self.url.trim().is_empty() {
            return Err(faucet_core::FaucetError::Config(
                "http-file: `url` must not be empty".into(),
            ));
        }
        faucet_core::validate_batch_size(self.batch_size)?;
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn auto_format_infers_from_extension() {
        assert_eq!(
            HttpFileSourceConfig::new("https://x/file.xlsx").resolved_format(),
            FileFormat::Excel
        );
        assert_eq!(
            HttpFileSourceConfig::new("https://x/file.XLS?q=1").resolved_format(),
            FileFormat::Excel
        );
        assert_eq!(
            HttpFileSourceConfig::new("https://x/data.csv").resolved_format(),
            FileFormat::Csv
        );
        // Graph /content has no extension → CSV by default.
        assert_eq!(
            HttpFileSourceConfig::new("https://graph/items/1/content").resolved_format(),
            FileFormat::Csv
        );
    }

    #[test]
    fn explicit_format_wins() {
        let mut c = HttpFileSourceConfig::new("https://x/file.csv");
        c.format = FileFormat::Excel;
        assert_eq!(c.resolved_format(), FileFormat::Excel);
    }

    #[test]
    fn validate_rejects_empty_url() {
        assert!(HttpFileSourceConfig::new("  ").validate().is_err());
        assert!(HttpFileSourceConfig::new("https://x/f.csv").validate().is_ok());
    }

    #[test]
    fn auth_defaults_to_none_and_parses_ref() {
        let c: HttpFileSourceConfig =
            serde_json::from_value(serde_json::json!({ "url": "https://x/f.csv" })).unwrap();
        assert!(matches!(c.auth, AuthSpec::Inline(HttpFileAuth::None)));
        let r: HttpFileSourceConfig = serde_json::from_value(
            serde_json::json!({ "url": "https://x/f.csv", "auth": { "ref": "graph" } }),
        )
        .unwrap();
        assert_eq!(r.auth.reference_name(), Some("graph"));
    }
}

//! The HTTP file source: download an authed blob and parse CSV/Excel.

use crate::config::{FileFormat, HttpFileAuth, HttpFileSourceConfig};
use async_trait::async_trait;
use faucet_core::{
    AuthSpec, Credential, FaucetError, SharedAuthProvider, Source, Stream, StreamPage,
};
use reqwest::{Client, RequestBuilder};
use serde_json::{Map, Value};
use std::collections::HashMap;
use std::pin::Pin;
use std::time::Duration;

/// A source that downloads a file from an authenticated HTTP/Graph URL and
/// parses it (CSV always; Excel behind the `excel` feature) into records.
pub struct HttpFileSource {
    config: HttpFileSourceConfig,
    client: Client,
    /// Optional shared auth provider (from `auth: { ref }` or a library caller).
    /// Takes precedence over inline auth.
    auth_provider: Option<SharedAuthProvider>,
}

impl HttpFileSource {
    /// Create a new source from the given config.
    pub fn new(config: HttpFileSourceConfig) -> Result<Self, FaucetError> {
        config.validate()?;
        let mut builder = Client::builder();
        if let Some(secs) = config.timeout_secs {
            builder = builder.timeout(Duration::from_secs(secs));
        } else {
            builder = builder.timeout(Duration::from_secs(60));
        }
        let client = builder
            .build()
            .map_err(|e| FaucetError::Config(format!("http-file: build HTTP client: {e}")))?;
        Ok(Self {
            config,
            client,
            auth_provider: None,
        })
    }

    /// Attach a shared [`AuthProvider`](faucet_core::AuthProvider) (resolved from
    /// `auth: { ref }` by the CLI, or injected by a library caller). Takes
    /// precedence over inline auth.
    pub fn with_auth_provider(mut self, provider: SharedAuthProvider) -> Self {
        self.auth_provider = Some(provider);
        self
    }

    /// Download the file bytes, applying auth.
    async fn fetch_bytes(&self, url: &str) -> Result<Vec<u8>, FaucetError> {
        let mut req = self.client.get(url);
        req = if let Some(provider) = &self.auth_provider {
            apply_credential(req, provider.credential().await?)
        } else {
            match self.config.auth.inline() {
                Some(auth) => apply_inline_auth(req, auth),
                None => req, // a `{ ref }` with no provider wired — send unauth'd
            }
        };
        let resp = req
            .send()
            .await
            .map_err(|e| FaucetError::Source(format!("http-file: request to {url} failed: {e}")))?;
        let status = resp.status();
        if !status.is_success() {
            let body = resp.text().await.unwrap_or_default();
            let body = body.chars().take(512).collect::<String>();
            return Err(FaucetError::HttpStatus {
                status: status.as_u16(),
                url: url.to_string(),
                body,
            });
        }
        Ok(resp
            .bytes()
            .await
            .map_err(|e| FaucetError::Source(format!("http-file: reading body of {url}: {e}")))?
            .to_vec())
    }

    /// Parse downloaded bytes into records per the resolved format.
    async fn parse(&self, bytes: &[u8]) -> Result<Vec<Value>, FaucetError> {
        match self.config.resolved_format() {
            FileFormat::Csv | FileFormat::Auto => {
                parse_csv(bytes, self.config.delimiter, self.config.has_headers).await
            }
            FileFormat::Excel => parse_excel(
                bytes,
                self.config.sheet.as_deref(),
                self.config.header_row,
            ),
        }
    }
}

/// Apply an inline [`HttpFileAuth`] to the request.
fn apply_inline_auth(req: RequestBuilder, auth: &HttpFileAuth) -> RequestBuilder {
    match auth {
        HttpFileAuth::None => req,
        HttpFileAuth::Bearer { token } => req.bearer_auth(token),
        HttpFileAuth::Basic { username, password } => req.basic_auth(username, Some(password)),
        HttpFileAuth::ApiKey { header, value } => req.header(header, value),
        HttpFileAuth::Custom { headers } => {
            let mut req = req;
            for (k, v) in headers {
                req = req.header(k, v);
            }
            req
        }
    }
}

/// Apply a shared-provider [`Credential`] to the request.
fn apply_credential(req: RequestBuilder, cred: Credential) -> RequestBuilder {
    match cred {
        Credential::Bearer(token) => req.bearer_auth(token),
        Credential::Token(token) => req.header(reqwest::header::AUTHORIZATION, token),
        Credential::Basic { username, password } => req.basic_auth(username, Some(password)),
        Credential::Header { name, value } => req.header(name, value),
    }
}

/// Parse CSV bytes into records. Header row (when `has_headers`) supplies field
/// names; otherwise fields are named `column_N`. Values are strings (like the
/// `csv` source). Pure (no network).
pub async fn parse_csv(
    bytes: &[u8],
    delimiter: u8,
    has_headers: bool,
) -> Result<Vec<Value>, FaucetError> {
    use futures::StreamExt as _;
    let mut rdr = csv_async::AsyncReaderBuilder::new()
        .has_headers(false)
        .delimiter(delimiter)
        .flexible(true)
        .create_reader(bytes);
    let mut records = rdr.records();
    let mut headers: Option<Vec<String>> = None;
    let mut out = Vec::new();
    while let Some(rec) = records.next().await {
        let rec = rec.map_err(|e| FaucetError::Source(format!("http-file: CSV parse error: {e}")))?;
        if has_headers && headers.is_none() {
            headers = Some(rec.iter().map(str::to_string).collect());
            continue;
        }
        let mut obj = Map::new();
        for (i, field) in rec.iter().enumerate() {
            let key = headers
                .as_ref()
                .and_then(|h| h.get(i).cloned())
                .unwrap_or_else(|| format!("column_{i}"));
            obj.insert(key, Value::String(field.to_string()));
        }
        out.push(Value::Object(obj));
    }
    Ok(out)
}

/// Parse Excel bytes into records. Requires the `excel` feature.
#[cfg(feature = "excel")]
pub fn parse_excel(
    bytes: &[u8],
    sheet: Option<&str>,
    header_row: usize,
) -> Result<Vec<Value>, FaucetError> {
    use calamine::{Data, Reader, Xlsx};
    let cursor = std::io::Cursor::new(bytes.to_vec());
    let mut wb: Xlsx<_> = calamine::open_workbook_from_rs(cursor)
        .map_err(|e| FaucetError::Source(format!("http-file: opening Excel workbook: {e}")))?;
    let names = wb.sheet_names().to_vec();
    let name = match sheet {
        Some(s) if names.iter().any(|n| n == s) => s.to_string(),
        Some(s) => match s.parse::<usize>() {
            Ok(idx) => names.get(idx).cloned().ok_or_else(|| {
                FaucetError::Source(format!("http-file: sheet index {idx} out of range"))
            })?,
            Err(_) => {
                return Err(FaucetError::Source(format!(
                    "http-file: sheet '{s}' not found (available: {})",
                    names.join(", ")
                )));
            }
        },
        None => names
            .first()
            .cloned()
            .ok_or_else(|| FaucetError::Source("http-file: workbook has no worksheets".into()))?,
    };
    let range = wb
        .worksheet_range(&name)
        .map_err(|e| FaucetError::Source(format!("http-file: reading sheet '{name}': {e}")))?;
    let rows: Vec<&[Data]> = range.rows().collect();
    let header = rows.get(header_row).ok_or_else(|| {
        FaucetError::Source(format!(
            "http-file: header_row {header_row} is beyond the sheet ({} rows)",
            rows.len()
        ))
    })?;
    let headers: Vec<String> = header.iter().map(cell_to_string).collect();
    let mut out = Vec::new();
    for row in rows.iter().skip(header_row + 1) {
        let mut obj = Map::new();
        for (i, cell) in row.iter().enumerate() {
            let key = headers
                .get(i)
                .cloned()
                .filter(|k| !k.is_empty())
                .unwrap_or_else(|| format!("column_{i}"));
            obj.insert(key, cell_to_value(cell));
        }
        out.push(Value::Object(obj));
    }
    Ok(out)
}

/// Stub when the `excel` feature is disabled — errors loudly rather than
/// silently mis-parsing an Excel blob as CSV.
#[cfg(not(feature = "excel"))]
pub fn parse_excel(
    _bytes: &[u8],
    _sheet: Option<&str>,
    _header_row: usize,
) -> Result<Vec<Value>, FaucetError> {
    Err(FaucetError::Config(
        "http-file: Excel parsing requires the `excel` feature — rebuild with `--features excel` \
         (e.g. `cargo install faucet-cli --features source-http-file-excel`)"
            .into(),
    ))
}

#[cfg(feature = "excel")]
fn cell_to_string(cell: &calamine::Data) -> String {
    use calamine::Data;
    match cell {
        Data::String(s) => s.clone(),
        Data::Empty => String::new(),
        other => other.to_string(),
    }
}

#[cfg(feature = "excel")]
fn cell_to_value(cell: &calamine::Data) -> Value {
    use calamine::Data;
    match cell {
        Data::Empty => Value::Null,
        Data::String(s) => Value::String(s.clone()),
        Data::Bool(b) => Value::Bool(*b),
        Data::Int(i) => Value::from(*i),
        Data::Float(f) => serde_json::Number::from_f64(*f)
            .map(Value::Number)
            .unwrap_or(Value::Null),
        Data::DateTime(dt) => Value::String(dt.to_string()),
        Data::DateTimeIso(s) | Data::DurationIso(s) => Value::String(s.clone()),
        Data::Error(e) => Value::String(format!("{e:?}")),
    }
}

#[async_trait]
impl Source for HttpFileSource {
    async fn fetch_with_context(
        &self,
        context: &HashMap<String, Value>,
    ) -> Result<Vec<Value>, FaucetError> {
        let url = if context.is_empty() {
            self.config.url.clone()
        } else {
            faucet_core::util::substitute_context(&self.config.url, context)
        };
        let bytes = self.fetch_bytes(&url).await?;
        self.parse(&bytes).await
    }

    fn stream_pages<'a>(
        &'a self,
        context: &'a HashMap<String, Value>,
        _batch_size: usize,
    ) -> Pin<Box<dyn Stream<Item = Result<StreamPage, FaucetError>> + Send + 'a>> {
        let batch_size = self.config.batch_size;
        Box::pin(async_stream::try_stream! {
            // A single blob is downloaded and parsed in full, then re-chunked
            // into pages of `batch_size` (0 = one page).
            let records = self.fetch_with_context(context).await?;
            if batch_size == 0 || records.is_empty() {
                yield StreamPage { records, bookmark: None };
            } else {
                let total = records.len();
                let mut iter = records.into_iter();
                let mut emitted = 0;
                loop {
                    let page: Vec<Value> = iter.by_ref().take(batch_size).collect();
                    if page.is_empty() { break; }
                    emitted += page.len();
                    let is_last = emitted >= total;
                    // No incremental replication → bookmark is always None.
                    yield StreamPage { records: page, bookmark: None };
                    if is_last { break; }
                }
            }
        })
    }

    fn config_schema(&self) -> Value {
        serde_json::to_value(schemars::schema_for!(HttpFileSourceConfig)).unwrap_or(Value::Null)
    }

    fn connector_name(&self) -> &'static str {
        "http-file"
    }
}

// Re-export so the CLI registry can inject a shared provider without importing
// the config module path directly.
impl HttpFileSource {
    /// The connector's inline auth reference name, if configured as `{ ref }`.
    pub fn auth_ref(config: &HttpFileSourceConfig) -> Option<&str> {
        match &config.auth {
            AuthSpec::Reference(r) => Some(&r.name),
            AuthSpec::Inline(_) => None,
        }
    }
}

