230	    // Index nodes by id for parent → children lookups.
231	    // parent id → child node ids. Keyed and valued by id (not Vec index) so the
232	    // failure cascade can look children up directly instead of indexing into a
233	    // HashMap's nondeterministic iteration order (#78/#24).
234	    let mut children_of: HashMap<String, Vec<String>> = HashMap::new();
235	    for n in nodes.iter() {
