244	    // Captured records per node id. Only populated for nodes that have
245	    // children (= are referenced by another node's `parent:`). Records are held
246	    // as `Arc<Value>` so the per-level snapshot clone and the per-child-unit
247	    // hand-off are pointer bumps, not deep clones of the JSON tree (#160).
248	    let captured: CapturedRecords = Arc::new(Mutex::new(HashMap::new()));
249	
250	    let mut outcomes: Vec<InvocationOutcome> = Vec::new();
251	    let mut skipped_subtrees: HashSet<String> = HashSet::new();
252	
253	    // Root cooperative-cancel token: the caller's (serve wires run-cancel /
254	    // timeout / shutdown) or a fresh one. Each level derives a child token so
255	    // an `on_error: stop` cancels only that level's invocations, while an
256	    // external cancel of the root propagates to every level (#146 H16).
257	    let cancel = opts.cancel.clone().unwrap_or_default();
258	    let opts = Arc::new(opts);
259	
260	    // We execute level-by-level. Each level is "every node whose parent is
261	    // already done." Roots are level 0. For each level, we spawn one task per
262	    // (node, parent-record) pair and await them all before moving on.
263	    let mut remaining: HashSet<String> = nodes.iter().map(|n| n.id.clone()).collect();
264	    let mut completed: HashSet<String> = HashSet::new();
265	    let nodes_by_id: HashMap<String, ExpandedNode> =
266	        nodes.into_iter().map(|n| (n.id.clone(), n)).collect();
267	
268	    // Per-parent projection: what to keep from each captured record so the
269	    // fan-out buffer holds only the fields children reference (#160).
270	    let projections = build_projections(&nodes_by_id, &children_of);
271	
272	    // Sort node ids in their original BFS row order so the executor is
273	    // deterministic — important for `on_error: stop`, where the first failure
274	    // halts the rest of the level.
275	    let bfs_order: Vec<String> = {
276	        let mut ids: Vec<(usize, String)> = nodes_by_id
277	            .values()
278	            .map(|n| (n.row_index, n.id.clone()))
279	            .collect();
280	        ids.sort_by_key(|(i, _)| *i);
281	        ids.into_iter().map(|(_, id)| id).collect()
282	    };
