# ─────────────────────────────────────────────────────────────────────────────
# Drivetrain migration template — GraphQL source → { JSONL | BigQuery }
# For taps like Shopify (Admin GraphQL). Same one-template / flip-sink model as
# rest.yaml: maintain the source+transforms here; flip with --param sink=…
#
#   faucet run drivetrain/templates/graphql.yaml \
#     --param sink=jsonl --param table=orders \
#     --param endpoint=https://acme.myshopify.com/admin/api/2024-10/graphql.json \
#     --param api_token=$SHOPIFY_TOKEN
# ─────────────────────────────────────────────────────────────────────────────
version: 1
name: drivetrain-graphql

params:
  sink:      { type: string, default: jsonl, description: "jsonl | bigquery" }
  table:     { type: string, required: true, description: "table_id / JSONL filename" }
  endpoint:  { type: string, required: true, description: "GraphQL endpoint URL" }
  api_token: { type: string, required: true, secret: true, description: "API token" }
  bq_project: { type: string, default: "REPLACE_ME_PROJECT", description: "BigQuery project_id" }
  bq_dataset: { type: string, default: "raw", description: "BigQuery dataset_id" }

pipeline:
  sources:
    default:
      type: graphql
      config:
        endpoint: "${param.endpoint}"
        auth:
          type: bearer
          config: { token: "${param.api_token}" }
        # Your query + the JSONPath to the node list. Edit here (one place).
        query: |
          query($cursor: String) {
            orders(first: 100, after: $cursor) {
              edges { node { id name createdAt } }
              pageInfo { hasNextPage endCursor }
            }
          }
        records_path: "$.data.orders.edges[*].node"
        variables: {}
        pagination:
          has_next_page_path: "$.data.orders.pageInfo.hasNextPage"
          cursor_path: "$.data.orders.pageInfo.endCursor"
          cursor_variable: cursor
          page_size_variable: first

  transforms:
    - type: keys_case
      config: { mode: snake }
    # cast / rename / json_encode to match your existing table exactly.

  sinks:
    jsonl:
      type: jsonl
      config: { path: "./drivetrain/out/${param.table}.jsonl" }
    bigquery:
      type: bigquery
      config:
        project_id: "${param.bq_project}"
        dataset_id: "${param.bq_dataset}"
        table_id: "${param.table}"
        write_mode: overwrite
        auth: { type: application_default }

matrix:
  - id: load
    sink: { ref: "${param.sink}" }

