249	    async fn fetch_all_with_context(
250	        &self,
251	        context: &HashMap<String, serde_json::Value>,
252	    ) -> Result<Vec<Value>, FaucetError> {
253	        self.config.validate()?;
254	
255	        let mut all_records = Vec::new();
256	        let mut pages_fetched = 0usize;
257	        let mut offset = 0usize;
258	        let mut page_number = None;
259	        let mut prev_fingerprint: Option<u64> = None;
260	        let mut fault_logged = false;
261	
262	        // Initialize pagination state.
263	        if let Some(XmlPagination::PageNumber { start_page, .. }) = &self.config.pagination {
264	            page_number = Some(*start_page);
265	        }
266	
267	        loop {
268	            if let Some(max) = self.config.max_pages
269	                && pages_fetched >= max
270	            {
271	                tracing::warn!("max pages ({max}) reached");
272	                break;
273	            }
274	
275	            let mut params = self.config.query_params.clone();
276	            self.apply_pagination_params(&mut params, page_number, offset);
277	
278	            let xml_text = self.execute_request(&params, context).await?;
279	            let records = self.extract_records_eager(&xml_text, &mut fault_logged)?;
280	
281	            let record_count = records.len();
282	            let fingerprint = page_fingerprint(&records);
283	            pages_fetched += 1;
284	
285	            // Loop guard: a server that ignores the page/offset parameter (or
286	            // clamps to the last page) returns the same non-empty page forever.
287	            // Stop when two consecutive pages are identical (audit #146 H4/H5) —
288	            // and do it BEFORE appending, so the duplicate page's records are
289	            // never emitted to the sink a second time (audit #321 M4).
290	            if record_count > 0 && prev_fingerprint == Some(fingerprint) {
291	                tracing::warn!(
292	                    "XML pagination returned an identical page; stopping to avoid an infinite loop"
293	                );
294	                break;
295	            }
296	            prev_fingerprint = Some(fingerprint);
297	            all_records.extend(records);
298	
299	            // Advance pagination or stop.
300	            match &self.config.pagination {
301	                Some(XmlPagination::PageNumber { page_size, .. }) => {
302	                    if record_count == 0 {
303	                        break;
304	                    }
305	                    // Stop if page_size is set and we got fewer records than the page size.
306	                    if let Some(size) = page_size
307	                        && record_count < *size
308	                    {
