124	/// The committed `schemas/faucet.schema.json` (generated under `--all-features`)
125	/// covers the current build's composed schema. Guards against forgetting to
126	/// regenerate after a connector/config change: every node the current build
127	/// emits must be present in the committed file. Regenerate with:
128	/// `cargo run --all-features -- schema config > schemas/faucet.schema.json`.
129	///
130	/// A **subset** check (not exact equality) so a smaller feature set than
131	/// `--all-features` — which produces fewer connector `oneOf` branches / config
132	/// fields — still passes, while an added or changed schema node in the current
133	/// build (in the all-features CI job the two are identical) is caught.
134	#[test]
135	fn committed_schema_covers_current_build() {
136	    let current = config_schema();
137	    let committed: Value = serde_json::from_str(include_str!("../../schemas/faucet.schema.json"))
138	        .expect("committed schema parses");
139	    if let Err(path) = is_subset(&current, &committed, String::new()) {
140	        panic!(
141	            "schemas/faucet.schema.json is stale at `{path}` — regenerate with \
142	             `cargo run --all-features -- schema config > schemas/faucet.schema.json`"
143	        );
144	    }
145	}
146	
147	/// Every node in `sub` must be present (deep-equal) in `sup`. Returns the JSON
148	/// pointer of the first divergence on failure.
149	fn is_subset(sub: &Value, sup: &Value, path: String) -> Result<(), String> {
150	    match (sub, sup) {
151	        (Value::Object(a), Value::Object(b)) => {
152	            for (k, va) in a {
153	                match b.get(k) {
154	                    Some(vb) => is_subset(va, vb, format!("{path}/{k}"))?,
155	                    None => return Err(format!("{path}/{k}")),
156	                }
157	            }
158	            Ok(())
159	        }
160	        (Value::Array(a), Value::Array(b)) => {
161	            // Order-insensitive membership: every element of `sub` must
162	            // deep-equal some element of `sup` (handles connector `oneOf`).
163	            for (i, va) in a.iter().enumerate() {
164	                if !b.iter().any(|vb| vb == va) {
165	                    return Err(format!("{path}/{i}"));
166	                }
167	            }
168	            Ok(())
169	        }
170	        _ if sub == sup => Ok(()),
171	        _ => Err(path),
172	    }
173	}
