1	//! Local sink output tracking — the provenance record a retention GC deletes
2	//! from (#587).
3	//!
4	//! A local run writes real files: `out.jsonl`, `rows.csv`, a directory of
5	//! UUID-named parquet parts. Repeated local iteration (or a long-running
6	//! `faucet serve` used for local testing) piles them up, so faucet grows a
7	//! retention garbage-collector for them. That GC has one hard requirement:
8	//!
9	//! > **It may only delete files faucet itself created.** Never a glob, never a
10	//! > directory wipe — not even for "clean all".
11	//!
12	//! Which means the deletion has to work from a *recorded list of concrete
13	//! paths*, and the only component that knows those paths is the sink that
14	//! opened them. A path cannot be re-derived after the fact:
15	//!
16	//! - The catalog stores a **canonical** dataset URI with `${now.*}` segments
17	//!   folded back to their tokens, so a dated path there is deliberately not the
18	//!   file that exists on disk.
19	//! - A rolling parquet sink names each part with a fresh UUID. Nothing outside
20	//!   the sink can enumerate them without globbing the directory — which is
21	//!   exactly what the guardrail forbids.
22	//!
23	//! So each local-file sink accumulates a [`LocalOutputLog`] as it opens files
24	//! and reports it through [`Sink::local_outputs`](crate::Sink::local_outputs);
25	//! the CLI records that list after a successful run and the GC deletes only
26	//! from it.
27	//!
28	//! ## Why `pre_existing` is tracked, and why the GC must honour it
29	//!
30	//! "faucet wrote this path" is not the same claim as "faucet created this file".
31	//! A sink pointed at an existing file — `append: true` onto a colleague's
32	//! export, or a mistyped path landing on a real file — writes to a file it did
33	//! not create. Deleting that on a retention sweep is data loss of somebody
34	//! else's data, and no retention window makes it acceptable.
35	//!
36	//! So the flag is captured **at the first open**, before the file is created
37	//! ([`LocalOutputLog::record_open`] takes it from a caller-supplied probe), and
38	//! it is sticky: a second run that truncates a path faucet created earlier is
39	//! still faucet's own output, and re-recording must not reclassify it. The GC
40	//! refuses to delete a `pre_existing` entry — including on an explicit,
41	//! single-path "delete now" — and says why instead.
42	
43	use std::collections::BTreeMap;
44	use std::path::{Path, PathBuf};
45	use std::sync::Mutex;
46	
47	/// One concrete local file a sink opened during a run.
48	#[derive(Debug, Clone, PartialEq, Eq)]
49	pub struct LocalOutput {
50	    /// The file the sink wrote, as the sink addressed it.
51	    pub path: PathBuf,
52	    /// The file already existed the first time this sink opened it — faucet
53	    /// appended to (or truncated) a file it did not create. A retention GC must
54	    /// never delete such a file; see the module docs.
55	    pub pre_existing: bool,
56	}
57	
58	impl LocalOutput {
59	    /// A file faucet created.
60	    pub fn created(path: impl Into<PathBuf>) -> Self {
61	        Self {
62	            path: path.into(),
63	            pre_existing: false,
64	        }
65	    }
66	
67	    /// A file that already existed when faucet first opened it.
68	    pub fn pre_existing(path: impl Into<PathBuf>) -> Self {
69	        Self {
70	            path: path.into(),
71	            pre_existing: true,
72	        }
73	    }
74	}
75	
76	/// Whether `path` already exists on disk — the probe a sink runs **before**
77	/// opening a file for the first time, to fill
78	/// [`LocalOutput::pre_existing`].
79	///
80	/// A path that cannot be stat-ed (a permission error on the parent, say) is
81	/// reported as `true`: the conservative answer, since it makes the GC leave the
82	/// file alone rather than delete something faucet may not have created.
83	pub fn probe_pre_existing(path: &Path) -> bool {
84	    match std::fs::symlink_metadata(path) {
85	        Ok(_) => true,
86	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => false,
87	        // Anything else (EACCES on the parent directory, EIO, a broken mount)
88	        // is not a "definitely absent" answer, so do not claim faucet created it.
89	        Err(_) => true,
90	    }
91	}
92	
93	/// A sink's accumulating list of the local files it has opened.
94	///
95	/// Shared shape for every local-file sink (and for third-party ones): dedup by
96	/// path, `pre_existing` fixed by the **first** open of each path, insertion
97	/// order preserved for stable reporting. Cheap enough to call on every open —
98	/// a file open already costs a syscall.
99	///
100	/// Poisoned-lock safety: the accumulator is provenance metadata, never on the
101	/// data path, so a poisoned mutex degrades to "record nothing" rather than
102	/// panicking a sink mid-write. A lost record means the GC does not know about
103	/// the file and leaves it on disk — the safe direction.
104	#[derive(Debug, Default)]
105	pub struct LocalOutputLog {
106	    /// Path → (`pre_existing`, insertion index). `BTreeMap` for the dedup;
107	    /// the index restores first-seen order on read.
108	    seen: Mutex<BTreeMap<PathBuf, (bool, usize)>>,
109	}
110	
111	impl LocalOutputLog {
112	    pub fn new() -> Self {
113	        Self::default()
114	    }
115	
116	    /// Record that the sink opened `path`, taking `pre_existing` from a probe
117	    /// run before the open (see [`probe_pre_existing`]).
118	    ///
119	    /// Idempotent per path: a re-open (the per-page `flush()` → reopen cycle the
120	    /// file sinks perform, or a later run truncating the same path) keeps the
121	    /// classification captured the first time.
122	    pub fn record_open(&self, path: impl Into<PathBuf>, pre_existing: bool) {
123	        let path = path.into();
124	        if let Ok(mut seen) = self.seen.lock() {
125	            let next = seen.len();
126	            seen.entry(path).or_insert((pre_existing, next));
127	        }
128	    }
129	
130	    /// Record a first open of `path`, probing the filesystem for
131	    /// `pre_existing` **only if** the path has not been recorded yet.
132	    ///
133	    /// This is the entry point for sinks whose open path is async or runs inside
134	    /// `spawn_blocking`: it keeps the stat off the hot path once the file is
135	    /// known, and it cannot reclassify an already-recorded path.
136	    pub fn record_open_probing(&self, path: impl Into<PathBuf>) {
137	        let path = path.into();
138	        let known = self
139	            .seen
140	            .lock()
141	            .map(|seen| seen.contains_key(&path))
142	            .unwrap_or(true);
143	        if !known {
144	            let pre_existing = probe_pre_existing(&path);
145	            self.record_open(path, pre_existing);
146	        }
147	    }
148	
149	    /// The files recorded so far, in first-seen order.
150	    pub fn snapshot(&self) -> Vec<LocalOutput> {
151	        let Ok(seen) = self.seen.lock() else {
152	            return Vec::new();
153	        };
154	        let mut rows: Vec<(usize, LocalOutput)> = seen
155	            .iter()
156	            .map(|(path, (pre_existing, idx))| {
157	                (
158	                    *idx,
159	                    LocalOutput {
160	                        path: path.clone(),
161	                        pre_existing: *pre_existing,
162	                    },
