3	use schemars::JsonSchema;
4	use serde::{Deserialize, Serialize};
5	
6	fn default_track() -> bool {
7	    true
8	}
9	
10	/// The top-level `local_outputs:` block: how long the local files this
11	/// pipeline's sinks write are kept, and whether faucet records them at all.
12	///
13	/// ```yaml
14	/// local_outputs:
15	///   retention_days: 3   # this pipeline's outputs are collectable after 3 days
16	/// ```
17	///
18	/// The block is optional. Without it a pipeline still records its local outputs
19	/// (so they can be listed and cleaned) and inherits the runtime's default
20	/// window — `--local-output-retention-days` /
21	/// `FAUCET_LOCAL_SINK_OUTPUT_RETENTION_DAYS`, itself 7 days by default.
22	///
23	/// Recording needs somewhere to record *to*: under `faucet serve` that is the
24	/// `--history` backend; for `faucet run` / `schedule` / `replicate` it is the
25	/// `catalog:` block's store. Without either, tracking is inert and a one-line
26	/// warning says so rather than failing the run — a pipeline must never break
27	/// because a housekeeping ledger was unavailable.
28	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
29	#[serde(deny_unknown_fields)]
30	pub struct LocalOutputsSpec {
31	    /// Record the local files this pipeline's sinks write, so they can be listed
32	    /// in the console and reclaimed by the GC. Default `true`.
33	    ///
34	    /// Setting `false` opts the pipeline out of the ledger entirely: its outputs
35	    /// are never listed and — because the GC only ever deletes recorded paths —
36	    /// never automatically deleted either.
37	    #[serde(default = "default_track")]
38	    pub track: bool,
39	
40	    /// Retention window for this pipeline's outputs, in days, overriding the
41	    /// runtime default. `0` keeps them forever.
42	    ///
43	    /// Measured from the last time faucet wrote the file, so an output a local
44	    /// run keeps refreshing does not expire underneath it.
45	    #[serde(default, skip_serializing_if = "Option::is_none")]
46	    pub retention_days: Option<u32>,
47	}
48	
49	impl Default for LocalOutputsSpec {
50	    fn default() -> Self {
51	        Self {
52	            track: true,
53	            retention_days: None,
54	        }
55	    }
56	}
57	
