# ═════════════════════════════════════════════════════════════════════════════
# iPaaS migration — postgres.py → { JSONL | BigQuery }
# Source of truth: DrivetrainAi/ipaas scripts/ipaas/postgres/postgres.py
#   psycopg2 server-side cursor, SELECT * FROM {schema}.{table}, full refresh.
#   faucet native `postgres` source runs one query per pipeline → parameterized
#   by schema+table (run once per table).
# ═════════════════════════════════════════════════════════════════════════════
version: 1
name: postgres-to-bigquery-or-jsonl

params:
  sink:       { type: string, default: bigquery, description: "Destination sink: jsonl | bigquery (bigquery = prod default)" }
  host:       { type: string, required: true, description: "Postgres host" }
  port:       { type: int,    default: 5432, description: "Postgres port" }
  database:   { type: string, required: true, description: "Postgres database" }
  user:       { type: string, required: true, description: "Postgres user" }
  password:   { type: string, required: true, secret: true, description: "Postgres password" }
  sslmode:    { type: string, default: require, description: "disable | require | verify-ca | verify-full" }
  schema:     { type: string, default: public, description: "Source schema" }
  table:      { type: string, required: true, description: "Source table; also table_id / JSONL filename" }
  bq_project: { type: string, default: "REPLACE_ME_PROJECT" }
  bq_dataset: { type: string, default: "raw" }
  bq_sa_key:  { type: string, default: "", secret: true, description: "BigQuery service-account key JSON (inline); required when sink=bigquery" }

pipeline:
  sources:
    default:
      type: postgres
      config:
        connection_url: "REDACTED"
        query: "SELECT * FROM ${param.schema}.${param.table}"

  transforms:
    - { type: keys_case, config: { mode: snake } }

  sinks:
    jsonl:
      type: jsonl
      config: { path: "./faucet-local-demo/out/postgres/${param.table}.jsonl" }
    bigquery:
      type: bigquery
      config:
        project_id: "${param.bq_project}"
        dataset_id: "${param.bq_dataset}"
        table_id: "${param.table}"
        write_mode: overwrite
        auth: { type: service_account_key, config: { json: "${param.bq_sa_key}" } }

matrix:
  - id: load
    sink: { ref: "${param.sink}" }

