// ── list ────────────────────────────────────────────────────────────────────

/** Columns the table can sort on. `updated` defaults to newest-first. */
const SORT_COLS = ["status", "name", "live", "newest", "params", "updated"];

export async function renderTemplates(container) {
  container.innerHTML = `
    <div class="page">
      <div class="page-head">
        <h1>Templates</h1>
        <button class="btn-ghost" id="t-refresh">↻</button>
        <button class="btn-primary" id="t-new">Register a template</button>
      </div>
      <div id="t-register" hidden></div>
      <div class="filters tpl-filters" id="t-filters" hidden>
        <input id="t-search" type="search" autocomplete="off"
          placeholder="search templates by id or description…" />
        <select id="t-filter" title="filter by release status or assigned channel">
          <option value="">All templates</option>
          <optgroup label="status">
            <option value="status:launched">Launched</option>
            <option value="status:draft">Draft</option>
            <option value="status:deprecated">Deprecated</option>
          </optgroup>
          <optgroup label="channel">
            <option value="chan:dev">dev</option>
            <option value="chan:test">test</option>
            <option value="chan:staging">staging</option>
            <option value="chan:pre-prod">pre-prod</option>
            <option value="chan:canary">canary</option>
            <option value="chan:prod">prod</option>
          </optgroup>
        </select>
        <span class="tpl-count" id="t-count"></span>
      </div>
      <div id="t-list"></div>
    </div>`;

  const list = container.querySelector("#t-list");
  const registerHost = container.querySelector("#t-register");
  const filters = container.querySelector("#t-filters");
  const search = container.querySelector("#t-search");
  const filterSel = container.querySelector("#t-filter");
  const countEl = container.querySelector("#t-count");
  let all = [];
  let sortKey = "name";
  let sortDir = "asc";

  container.querySelector("#t-new").onclick = () => {
    registerHost.hidden = !registerHost.hidden;
    if (!registerHost.hidden && !registerHost.childElementCount) {
      registerHost.appendChild(registerPanel(() => load()));
    }
  };
  container.querySelector("#t-refresh").onclick = () => load();
  search.oninput = () => render();
  filterSel.onchange = () => render();

  // A template matches when it passes the free-text search (id/description) AND
  // the status/channel dropdown. Everything is client-side — the registry is
  // small, so there is no server round-trip.
  function matches(t) {
    const q = search.value.trim().toLowerCase();
    if (
      q &&
      !((t.id || "").toLowerCase().includes(q) || (t.description || "").toLowerCase().includes(q))
    )
      return false;
    const f = filterSel.value;
    const st = t.state || {};
    if (f.startsWith("status:")) return (st.status || "draft") === f.slice(7);
    if (f.startsWith("chan:")) return !!(st.tags && Object.prototype.hasOwnProperty.call(st.tags, f.slice(5)));
    return true;
  }

  function sortVal(t, key) {
    const st = t.state || {};
    switch (key) {
      case "name": return (t.id || "").toLowerCase();
      case "updated": return t.created_at || "";
      case "params": return Object.keys(t.params || {}).length;
      case "live": return st.stable ?? -1;
      case "newest": return st.newest ?? t.version ?? -1;
      case "status": return st.status || "";
      default: return "";
    }
  }

  function render() {
    const rows = all.filter(matches).sort((a, b) => {
      const av = sortVal(a, sortKey);
      const bv = sortVal(b, sortKey);
      const c = av < bv ? -1 : av > bv ? 1 : 0;
      return sortDir === "asc" ? c : -c;
    });
    countEl.textContent = `${rows.length} of ${all.length}`;
    if (!rows.length) {
      list.innerHTML = `<div class="empty">No templates match the current search / filter.</div>`;
      return;
    }
    list.innerHTML = tableHtml(rows, sortKey, sortDir);
    list.querySelectorAll("th[data-sort]").forEach((th) => {
      th.onclick = () => {
        const k = th.dataset.sort;
        if (sortKey === k) sortDir = sortDir === "asc" ? "desc" : "asc";
        else {
          sortKey = k;
          sortDir = k === "updated" ? "desc" : "asc"; // recency reads best newest-first
        }
        render();
      };
    });
    list.querySelectorAll("tr[data-id]").forEach((tr) => {
      tr.onclick = () => navigate(`#/templates/${encodeURIComponent(tr.dataset.id)}`);
    });
  }

  async function load() {
    try {
      const data = await api("/v1/templates");
      all = data.templates || [];
      list.innerHTML = "";
      if (!all.length) {
        filters.hidden = true;
        list.innerHTML = `<div class="empty">No templates registered yet — register one to give operators a parameterized, versioned pipeline to trigger.</div>`;
        return;
      }
      filters.hidden = false;
      render(); // keeps any active search term / sort / filter across a refresh
    } catch (e) {
      filters.hidden = true;
      if (templatesUnavailable(e)) list.innerHTML = `<div class="empty">${TEMPLATES_MISSING}</div>`;
      else toast(e.message, "error");
    }
  }

  await load();
}

function sortArrow(key, sortKey, sortDir) {
  if (key !== sortKey) return "";
  return sortDir === "asc" ? ' <span class="tpl-arw">▲</span>' : ' <span class="tpl-arw">▼</span>';
}

/** The whole table as one HTML string; sort + row-nav are wired by the caller. */
function tableHtml(rows, sortKey, sortDir) {
  const th = (key, label, cls) =>
    `<th data-sort="${key}" class="sortable${cls ? " " + cls : ""}">${label}${sortArrow(key, sortKey, sortDir)}</th>`;
  const head = `<table class="tpl-table"><thead><tr>
      ${th("status", "Status")}
      ${th("name", "Name")}
      ${th("live", "Live", "num")}
      ${th("newest", "Newest", "num")}
      ${th("params", "Params", "num")}
      <th>Channels</th>
      ${th("updated", "Last updated")}
    </tr></thead><tbody>`;
  const body = rows
    .map((t) => {
      const st = t.state || {};
      const params = Object.keys(t.params || {}).length;
      const live = st.stable == null ? "—" : `v${st.stable}`;
      const newest = `v${st.newest ?? t.version}`;
      const chans =
        Object.keys(st.tags || {})
          .sort()
          .map((c) => `<span class="pill pill-chan">${escapeHtml(c)}</span>`)
          .join(" ") || `<span class="tpl-dim">—</span>`;
      return `<tr data-id="${escapeHtml(t.id)}">
        <td>${statusPill(st.status || "draft")}</td>
        <td class="tpl-name"><b class="mono">${escapeHtml(t.id)}</b>${
          t.description ? `<span class="tpl-row-desc">${escapeHtml(t.description)}</span>` : ""
        }</td>
        <td class="num">${live}</td>
        <td class="num">${newest}</td>
        <td class="num">${params}</td>
        <td>${chans}</td>
        <td class="tpl-dim">${fmtTime(t.created_at)}</td>
      </tr>`;
    })
    .join("");
  return head + body + `</tbody></table>`;
}

