/* Templates list — sortable / filterable table (#444) */
.tpl-filters { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.tpl-filters #t-search { flex: 1 1 260px; }
.tpl-count { font-size: 0.8rem; color: var(--ink-faint); margin-left: auto; font-variant-numeric: tabular-nums; }
.tpl-table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
.tpl-table th, .tpl-table td { text-align: left; padding: 10px 12px; border-bottom: 1px solid var(--border); vertical-align: middle; }
.tpl-table thead th { font-size: 0.72rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--ink-faint); font-weight: 600; white-space: nowrap; }
.tpl-table th.sortable { cursor: pointer; user-select: none; }
.tpl-table th.sortable:hover { color: var(--ink-dim); }
.tpl-table th.num, .tpl-table td.num { text-align: right; font-variant-numeric: tabular-nums; }
.tpl-arw { font-size: 0.7em; }
.tpl-table tbody tr { cursor: pointer; }
.tpl-table tbody tr:hover { background: var(--surface-2); }
.tpl-name { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.tpl-name b { font-weight: 600; }
.tpl-dim { color: var(--ink-faint); white-space: nowrap; }
.pill-chan { text-transform: none; }

.tpl-h2 { margin: 26px 0 10px; font-size: 0.95rem; color: var(--ink-dim); }

