// Self-heal once, on the first page. `begin_overwrite` may have run on a
// *different* sink instance (the executor drives it on a throwaway sink
// for group-level overwrite), so this instance cannot rely on an
// in-memory flag — it verifies the real BQ objects instead:
//   • target missing/schemaless + `create_table` → create it from this
//     page's sample (the schema source `CREATE … LIKE` needs);
//   • staging clone created `IF NOT EXISTS`, so a group-level
//     `begin_overwrite` that already staged a pre-existing target is
//     never clobbered (which would drop a concurrent fan-out invocation's
//     rows).
if !self.overwrite_setup.swap(true, Ordering::AcqRel) {
    if !self.target_has_schema().await? {
        if !self.config.create_table {
            return Err(FaucetError::Sink(format!(
                "BigQuery overwrite target {}.{}.{} does not exist (or has no \
                 schema) and `create_table` is disabled",
                self.config.project_id, self.config.dataset_id, self.config.table_id
            )));
        }
        self.create_target_from_sample(records).await?;
        self.table_ready.store(true, Ordering::Release);
    }
    self.run_ddl(format!(
        "CREATE TABLE IF NOT EXISTS {} LIKE {}",
        self.overwrite_temp_ref(),
        self.table_ref()
