async fn target_has_schema(&self) -> Result<bool, FaucetError> {
    match self.fetch_schema_fields().await {
        Ok(fields) => Ok(!fields.is_empty()),
        Err(e) if is_table_not_found(&e) => Ok(false),
        Err(e) => Err(FaucetError::Sink(format!(
