213	fn extract_string(body: &Value, path: &str) -> Option<String> {
214	    let results = body.query(path).ok()?;
215	    match results.first()? {
216	        Value::String(s) => Some(s.clone()),
217	        // Accept numbers/bools as tokens by converting to string.
218	        Value::Number(n) => Some(n.to_string()),
219	        _ => None,
220	    }
221	}
