fn build_load_job_json(
    project: &str,
    dataset: &str,
    table: &str,
    write_disposition: &str,
    location: Option<&str>,
) -> Value {
    build_load_job_json_fmt(
        project,
        dataset,
        table,
        write_disposition,
        location,
        "NEWLINE_DELIMITED_JSON",
        None,
        false,
    )
}

/// Generalized load-job JSON: `source_format` selects NDJSON vs CSV, `skip_rows`
/// sets `skipLeadingRows` (CSV headers), and `autodetect` lets BigQuery infer the
/// schema when the target may not exist yet (the native byte-passthrough path,
/// #633). Keeps `ignoreUnknownValues` so an extra column never fails a load.
#[allow(clippy::too_many_arguments)]
fn build_load_job_json_fmt(
    project: &str,
    dataset: &str,
    table: &str,
    write_disposition: &str,
    location: Option<&str>,
    source_format: &str,
    skip_rows: Option<u64>,
    autodetect: bool,
) -> Value {
    let mut load = serde_json::json!({
        "destinationTable": {
            "projectId": project,
            "datasetId": dataset,
            "tableId": table,
        },
        "sourceFormat": source_format,
        "writeDisposition": write_disposition,
        "ignoreUnknownValues": true,
        "autodetect": autodetect,
    });
    if let Some(n) = skip_rows {
        load["skipLeadingRows"] = serde_json::json!(n);
    }
    let mut job = serde_json::json!({ "configuration": { "load": load } });
    if let Some(loc) = location {
        job["jobReference"] = serde_json::json!({
            "projectId": project,
            "location": loc,
        });
    }
    job
}

