async fn load_native(
    &self,
    batch: faucet_core::NativeBatch,
    scope: &str,
    ctx: faucet_core::NativeLoadContext,
) -> Result<usize, FaucetError> {
    let _ = scope; // v1: no per-scope isolation on the native load path.
    // Overwrite truncates on the first batch (which opens the session), appends
    // thereafter. Because every page of an object feeds ONE resumable session
    // finalized in `flush`, this is one atomic WRITE_TRUNCATE load per object —
    // not a truncate-then-append across pages.
    let write_disposition = if ctx.write_mode == faucet_core::WriteMode::Overwrite
        && ctx.first_batch
    {
        "WRITE_TRUNCATE"
    } else {
        "WRITE_APPEND"
    };
    let rows = batch.records.unwrap_or(0) as usize;
    // Drain the payload to bytes (bounded by the source's batch size).
    let raw = match batch.payload {
        faucet_core::NativePayload::Bytes(b) => b,
        faucet_core::NativePayload::Stream(mut s) => {
            use futures::StreamExt;
            let mut buf = Vec::new();
            while let Some(chunk) = s.next().await {
                buf.extend_from_slice(&chunk?);
            }
            buf
        }
    };
    if raw.is_empty() {
        return Ok(0);
    }
    // Explicit all-STRING schema from the batch's own columns: never rely on
    // `autodetect` (it mis-infers DATE/NUMERIC from all-string data and then
    // fails a non-matching later row). Matches the `Value` write path.
    let schema =
        native_batch_columns(&raw, batch.format, batch.csv.delimiter).and_then(all_string_schema);

    match batch.format {
        // NDJSON streams into the per-object resumable session (one load job,
        // finalized in `flush`; ~8 MiB bounded memory) — the same efficient path
        // the `Value` media-load uses, but fed straight from source bytes.
        faucet_core::NativeFormat::NdJson => {
            self.feed_session_bytes(&self.config.table_id, write_disposition, schema, &raw)
                .await?;
            Ok(rows)
        }
        // CSV isn't NDJSON-shaped for the resumable session, so it takes a
        // discrete CSV load job per batch (no built-in source emits this today).
        faucet_core::NativeFormat::Csv => {
            let skip_rows = if batch.csv.has_header { Some(1) } else { None };
            let autodetect_fallback = schema.is_none();
            let media = gzip(&raw)?;
            let job_json = build_load_job_json_full(
                &self.config.project_id,
                &self.config.dataset_id,
                &self.config.table_id,
                write_disposition,
                self.config.location.as_deref(),
                "CSV",
                skip_rows,
                schema,
                autodetect_fallback,
            )
            .to_string();
            let loaded = self.load_media(&job_json, &media).await?;
            Ok(loaded as usize)
        }
        other => Err(FaucetError::Sink(format!(
            "bigquery load_native: unsupported format {other:?}"
        ))),
    }
}

