async fn load_native_ndjson_uses_explicit_string_schema_and_returns_output_rows() {
    let server = MockServer::start().await;
    mount_token_endpoint(&server).await;
    mount_load(&server, "job-native-1", "2").await;
    let (sink, _sa) = build_sink(&server, native_config(&server)).await;

    let batch = NativeBatch::bytes(
        NativeFormat::NdJson,
        b"{\"Id\":\"1\",\"Amount\":\"9\"}\n{\"Id\":\"2\",\"Amount\":\"x\"}\n".to_vec(),
    )
    .with_records(Some(2));
    let ctx = NativeLoadContext {
        write_mode: WriteMode::Append,
        first_batch: true,
    };
    let n = sink.load_native(batch, "p::row", ctx).await.expect("load ok");
    // Row count comes from the load job's statistics, not the source hint.
    assert_eq!(n, 2);

    let body = upload_bodies(&server).await.join("\n");
    // The job-config part is plain text in the multipart body (part 2 is gzipped).
    assert!(body.contains("NEWLINE_DELIMITED_JSON"), "{body:.400}");
    assert!(body.contains("\"autodetect\":false"), "autodetect must be off");
    assert!(body.contains("\"WRITE_APPEND\""));
    // An explicit all-STRING schema for the payload's columns — the fix that
    // stops BigQuery autodetect from mis-inferring a type and failing a later row.
    assert!(body.contains("\"name\":\"Id\",\"type\":\"STRING\""), "{body:.400}");
    assert!(body.contains("\"name\":\"Amount\",\"type\":\"STRING\""));
}

