fn stream_native<'a>(
    &'a self,
    context: &'a HashMap<String, Value>,
    format: faucet_core::NativeFormat,
    batch_size: usize,
) -> Pin<Box<dyn Stream<Item = Result<faucet_core::NativeBatch, FaucetError>> + Send + 'a>> {
