   the URI truncates at the same x on every row (#646). */
.ds-table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.ds-table thead th {
  text-align: left; font-size: 0.68rem; letter-spacing: 0.07em; text-transform: uppercase;
  color: var(--ink-faint); font-weight: 600; padding: 8px 14px; border-bottom: 1px solid var(--border);
}
.ds-table tbody td { padding: 11px 14px; border-bottom: 1px solid var(--border); vertical-align: middle; }
.ds-table tbody tr:last-child td { border-bottom: none; }
.ds-tr { cursor: pointer; }
.ds-tr:hover td { background: color-mix(in srgb, var(--ink-faint) 8%, transparent); }
.ds-uri { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }
.ds-meta { font-family: var(--font-mono); font-size: 0.8rem; color: var(--ink-dim); white-space: nowrap; }
.ds-num { text-align: right; }
.ds-time { color: var(--ink-faint); }
/* Fixed widths; column 2 (URI) takes the rest and ellipsises uniformly. */
.ds-table th:nth-child(1), .ds-table td:nth-child(1) { width: 92px; }
.ds-table th:nth-child(3), .ds-table td:nth-child(3) { width: 92px; }
.ds-table th:nth-child(4), .ds-table td:nth-child(4) { width: 74px; }
