// Comprehensive UI sweep: routes × themes × interactions.
// Usage: node sweep.mjs <theme> <outdir>
import fs from "fs";
const theme = process.argv[2] || "light";
const outdir = process.argv[3] || "/tmp";
const BASE = "http://127.0.0.1:18081";

async function newTab(url) {
  const t = await (await fetch(`http://127.0.0.1:9333/json/new?${encodeURIComponent(url)}`, { method: "PUT" })).json();
  const ws = new WebSocket(t.webSocketDebuggerUrl);
  let id = 0; const p = new Map();
  ws.addEventListener("message", (e) => {
    const m = JSON.parse(e.data);
    if (m.id && p.has(m.id)) { p.get(m.id)(m.result); p.delete(m.id); }
  });
  await new Promise((r) => ws.addEventListener("open", r));
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; p.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  await send("Page.enable"); await send("Runtime.enable");
  return { ws, send, close: () => ws.close(), target: t.id };
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function shot(tab, name) {
  const s = await tab.send("Page.captureScreenshot", { format: "png" });
  fs.writeFileSync(`${outdir}/${name}.png`, Buffer.from(s.data, "base64"));
  console.log("  shot", name);
}
async function evalJs(tab, expression) {
  const r = await tab.send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
  return r.result && r.result.value;
}
async function goto(tab, hash) {
  await evalJs(tab, `location.hash=${JSON.stringify(hash)}`);
  await sleep(2500);
}

// 1) Prime theme on the origin, then reload.
const boot = await newTab(BASE + "/");
await sleep(1500);
await evalJs(boot, `localStorage.setItem('faucet.theme', ${JSON.stringify(theme)}); localStorage.setItem('faucet.token','');`);
await evalJs(boot, `document.documentElement.setAttribute('data-theme', ${JSON.stringify(theme)})`);
boot.close();

const tab = await newTab(BASE + "/#/runs");
await sleep(3500);
await evalJs(tab, `document.documentElement.setAttribute('data-theme', ${JSON.stringify(theme)})`);
await sleep(400);

// RUNS
await goto(tab, "#/runs");
await evalJs(tab, `document.documentElement.setAttribute('data-theme', ${JSON.stringify(theme)})`);
await sleep(300);
await shot(tab, `runs_${theme}`);

// DATASETS list — top, then scrolled (sticky header check)
await goto(tab, "#/catalog");
await shot(tab, `datasets_${theme}`);
// open kind dropdown
await evalJs(tab, `(document.querySelector('#f-kind-dd .dd-btn')||document.querySelector('#f-kind-dd button'))?.click()`);
await sleep(500);
await shot(tab, `datasets_kinddd_${theme}`);
await evalJs(tab, `document.body.click()`); await sleep(300);
// scroll to test sticky header
await evalJs(tab, `window.scrollTo(0, 900)`);
await sleep(500);
await shot(tab, `datasets_scrolled_${theme}`);
await evalJs(tab, `window.scrollTo(0, 0)`); await sleep(300);

// DATASET DETAIL — first row's dataset, expand preview
const firstId = await evalJs(tab, `(async()=>{const d=await (await fetch('/v1/catalog/datasets?limit=50')).json(); const arr=d.datasets||d; return arr && arr.length? arr[0].id : null;})()`);
if (firstId) {
  await goto(tab, `#/catalog/${firstId}`);
  await shot(tab, `detail_${theme}`);
  // expand Manage disclosure if present
  await evalJs(tab, `document.querySelector('.lo-manage')?.setAttribute('open','')`);
  await sleep(300);
  await shot(tab, `detail_manage_${theme}`);
}

// WIDE PREVIEW dataset if it exists (wide-preview-demo)
const wideId = await evalJs(tab, `(async()=>{const d=await (await fetch('/v1/catalog/datasets?limit=200')).json(); const arr=d.datasets||d; const w=(arr||[]).find(x=>/wide|jsonl/i.test(x.uri||'')); return w?w.id:null;})()`);
if (wideId) {
  await goto(tab, `#/catalog/${wideId}`);
  // click a Preview button
  await evalJs(tab, `[...document.querySelectorAll('button')].find(b=>/preview/i.test(b.textContent))?.click()`);
  await sleep(1600);
  await shot(tab, `wide_preview_${theme}`);
}

// LINEAGE
await goto(tab, "#/lineage");
await sleep(1200);
await shot(tab, `lineage_${theme}`);

// TEMPLATES
await goto(tab, "#/templates");
await shot(tab, `templates_${theme}`);
const tplId = await evalJs(tab, `(async()=>{const d=await (await fetch('/v1/templates')).json(); const arr=d.templates||d; return arr&&arr.length? (arr[0].id||arr[0].name):null;})()`);
if (tplId) {
  await goto(tab, `#/templates/${tplId}`);
  await shot(tab, `template_detail_${theme}`);
}

// SCHEMAS + SUBMIT
await goto(tab, "#/schemas");
await shot(tab, `schemas_${theme}`);
await goto(tab, "#/submit");
await shot(tab, `submit_${theme}`);

tab.close();
console.log("done", theme);
process.exit(0);

