import fs from "fs";
const theme = process.argv[2] || "light";
const id = process.argv[3];
const out = process.argv[4];
const BASE = "http://127.0.0.1:18081";
async function newTab(url) {
  const t = await (await fetch(`http://127.0.0.1:9333/json/new?${encodeURIComponent(url)}`, { method: "PUT" })).json();
  const ws = new WebSocket(t.webSocketDebuggerUrl);
  let id = 0; const p = new Map();
  ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); if (m.id && p.has(m.id)) { p.get(m.id)(m.result); p.delete(m.id); } });
  await new Promise((r) => ws.addEventListener("open", r));
  const send = (method, params = {}) => new Promise((r) => { const i = ++id; p.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  await send("Page.enable"); await send("Runtime.enable");
  return { ws, send, close: () => ws.close() };
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const boot = await newTab(BASE + "/");
await sleep(1200);
await boot.send("Runtime.evaluate", { expression: `localStorage.setItem('faucet.theme', ${JSON.stringify(theme)})` });
boot.close();
const tab = await newTab(`${BASE}/#/catalog/${id}`);
await sleep(3500);
await tab.send("Runtime.evaluate", { expression: `document.documentElement.setAttribute('data-theme', ${JSON.stringify(theme)})` });
await sleep(400);
// click Preview / Load
await tab.send("Runtime.evaluate", { expression: `[...document.querySelectorAll('button')].find(b=>/preview/i.test(b.textContent))?.click()`, awaitPromise: true });
await sleep(1500);
await tab.send("Runtime.evaluate", { expression: `[...document.querySelectorAll('button')].find(b=>/^\\s*load\\s*$/i.test(b.textContent))?.click()`, awaitPromise: true });
await sleep(1800);
// scroll the preview table container a bit right to prove horizontal scroll
await tab.send("Runtime.evaluate", { expression: `const c=document.querySelector('.dp-scroll,.dp-table')?.closest('div'); if(c){c.scrollLeft=300;}` });
await sleep(400);
const s = await tab.send("Page.captureScreenshot", { format: "png" });
fs.writeFileSync(out, Buffer.from(s.data, "base64"));
tab.close();
console.log("shot", out);
process.exit(0);

