1	// Pipeline template registry (#444): the Templates browser and the per-template
2	// **versions page** — one row per registered version showing which channels point
3	// at it, with the release controls (assign a channel, launch, roll back,
4	// deprecate) and a typed trigger form built from the template's `params:` block.
5	//
6	// The lifecycle model this view renders:
7	//   • registering a version never moves callers — it only extends the build list
8	//   • `launch` is the one mindful step that moves `stable` (and so unpinned runs)
9	//   • `stable` / `previous` / `newest` are derived; `dev`…`prod` are assignable
10	import { api, toast } from "../api.js";
11	import { navigate } from "../router.js";
12	import { escapeHtml, mdInline } from "../utils.js";
13	import { fmtTime } from "./runs.js";
14	
15	const TEMPLATES_MISSING =
16	  "The pipeline template endpoints are not available on this server " +
17	  "(faucet was built without the `templates` feature, or no --template-store was configured).";
18	
19	/** Channels a user may point at a version. Derived ones are never assignable. */
20	export const ASSIGNABLE = ["dev", "test", "staging", "pre-prod", "canary", "prod"];
21	
22	/** A route is not wired at all when the feature is compiled out: bare 404. */
23	export function templatesUnavailable(e) {
24	  return e && e.status === 404 && !e.code;
25	}
26	
27	function statusPill(status) {
28	  const cls = { launched: "pill-completed", draft: "pill-queued", deprecated: "pill-cancelled" };
29	  return `<span class="pill ${cls[status] || ""}">${escapeHtml(status)}</span>`;
30	}
31	
32	// ── list ────────────────────────────────────────────────────────────────────
33	
34	export async function renderTemplates(container) {
35	  container.innerHTML = `
36	    <div class="page">
37	      <div class="page-head">
38	        <h1>Templates</h1>
39	        <button class="btn-ghost" id="t-refresh">↻</button>
40	        <button class="btn-primary" id="t-new">Register a template</button>
41	      </div>
42	      <div id="t-register" hidden></div>
43	      <div class="filters" id="t-filters" hidden>
44	        <input id="t-search" type="search" autocomplete="off"
45	          placeholder="search templates by id or description…" />
46	        <div class="tpl-status-filter" id="t-status-filter" role="group" aria-label="Filter by status">
47	          <button type="button" class="tpl-chip is-on" data-status="launched">launched</button>
48	          <button type="button" class="tpl-chip is-on" data-status="draft">draft</button>
49	          <button type="button" class="tpl-chip" data-status="deprecated">deprecated</button>
50	        </div>
51	      </div>
52	      <div class="tpl-list-head" id="t-list-head" hidden>
53	        <span>status</span>
54	        <button type="button" class="tpl-sort" data-sort="name">name<span class="tpl-sort-caret"></span></button>
55	        <button type="button" class="tpl-sort tpl-col-r" data-sort="updated">last updated<span class="tpl-sort-caret"></span></button>
56	        <span class="tpl-col-r">live</span>
57	        <span class="tpl-col-r">newest</span>
58	        <span class="tpl-col-r">params</span>
59	      </div>
60	      <div id="t-list" class="runs-list"></div>
61	    </div>`;
62	
63	  const list = container.querySelector("#t-list");
64	  const registerHost = container.querySelector("#t-register");
65	  const filters = container.querySelector("#t-filters");
66	  const listHead = container.querySelector("#t-list-head");
67	  const search = container.querySelector("#t-search");
68	  let all = [];
69	
70	  // Column sort — alphabetical by name is the default; clicking a sortable header
71	  // sets the column and toggles asc/desc on repeat clicks. Status is a filter
72	  // (below), not a sort column.
73	  const sort = { col: "name", dir: 1 };
74	  const sortKey = {
75	    name: (t) => (t.id || "").toLowerCase(),
76	    updated: (t) => new Date(t.created_at || 0).getTime() || 0,
77	  };
78	  listHead.querySelectorAll(".tpl-sort").forEach((btn) => {
79	    btn.onclick = () => {
80	      const col = btn.dataset.sort;
81	      if (sort.col === col) sort.dir *= -1;
82	      else { sort.col = col; sort.dir = 1; }
83	      render();
84	    };
85	  });
86	
87	  // Status filter — launched + draft on by default; deprecated hidden until its
88	  // chip is toggled on.
89	  const statusFilter = new Set(["launched", "draft"]);
90	  container.querySelectorAll("#t-status-filter .tpl-chip").forEach((chip) => {
91	    chip.onclick = () => {
92	      const s = chip.dataset.status;
93	      if (statusFilter.has(s)) statusFilter.delete(s);
94	      else statusFilter.add(s);
95	      chip.classList.toggle("is-on", statusFilter.has(s));
96	      render();
97	    };
98	  });
99	
100	  container.querySelector("#t-new").onclick = () => {
101	    registerHost.hidden = !registerHost.hidden;
102	    if (!registerHost.hidden && !registerHost.childElementCount) {
103	      registerHost.appendChild(registerPanel(() => load()));
104	    }
105	  };
106	  container.querySelector("#t-refresh").onclick = () => load();
107	  search.oninput = () => render();
108	
109	  // Client-side filter over the loaded set — match id or description,
110	  // case-insensitive. The registry is small, so there's no server round-trip.
111	  function render() {
112	    const q = search.value.trim().toLowerCase();
113	    const rows = all.filter((t) => {
114	      const status = (t.state || {}).status || "draft";
115	      if (!statusFilter.has(status)) return false;
116	      if (q && !((t.id || "").toLowerCase().includes(q) || (t.description || "").toLowerCase().includes(q))) return false;
117	      return true;
118	    });
119	    const key = sortKey[sort.col];
120	    if (key) {
121	      rows.sort((a, b) => {
122	        const av = key(a), bv = key(b);
123	        return (av < bv ? -1 : av > bv ? 1 : 0) * sort.dir;
124	      });
125	    }
126	    updateSortCarets();
127	    list.innerHTML = "";
128	    listHead.hidden = !rows.length; // only show the column header when rows are shown
129	    if (!rows.length) {
130	      const why = q
131	        ? `No templates match “${escapeHtml(search.value.trim())}”.`
132	        : "No templates match the selected status filter.";
133	      list.innerHTML = `<div class="empty">${why}</div>`;
134	      return;
135	    }
136	    for (const t of rows) list.appendChild(listRow(t));
137	  }
138	
139	  // Reflect the active sort on the header: ▲/▼ on the sorted column, a faint ↕
140	  // hint on the other sortable columns.
141	  function updateSortCarets() {
142	    listHead.querySelectorAll(".tpl-sort").forEach((btn) => {
143	      const active = sort.col === btn.dataset.sort;
144	      btn.classList.toggle("is-active", active);
145	      btn.setAttribute("aria-sort", active ? (sort.dir > 0 ? "ascending" : "descending") : "none");
146	      btn.querySelector(".tpl-sort-caret").textContent = active ? (sort.dir > 0 ? " ▲" : " ▼") : " ↕";
147	    });
148	  }
149	
150	  async function load() {
151	    try {
152	      const data = await api("/v1/templates");
153	      all = data.templates || [];
154	      list.innerHTML = "";
155	      if (!all.length) {
156	        filters.hidden = true;
157	        listHead.hidden = true;
158	        list.innerHTML = `<div class="empty">No templates registered yet — register one to give operators a parameterized, versioned pipeline to trigger.</div>`;
159	        return;
160	      }
161	      filters.hidden = false;
162	      render(); // keeps any active search term across a refresh
163	    } catch (e) {
164	      filters.hidden = true;
165	      listHead.hidden = true;
166	      if (templatesUnavailable(e)) list.innerHTML = `<div class="empty">${TEMPLATES_MISSING}</div>`;
167	      else toast(e.message, "error");
168	    }
169	  }
170	
171	  await load();
172	}
173	
174	function listRow(t) {
175	  const st = t.state || {};
176	  const el = document.createElement("div");
177	  el.className = "run-row tpl-row";
178	  el.onclick = () => navigate(`#/templates/${encodeURIComponent(t.id)}`);
179	  const params = Object.keys(t.params || {}).length;
