329	/** Which channels — derived and assigned — currently point at `v`. */
330	function channelsFor(v, st) {
331	  const out = [];
332	  if (st.stable === v) out.push(["stable", "pill-completed"]);
333	  if (st.previous === v) out.push(["previous", "pill-cancelled"]);
334	  if (st.newest === v) out.push(["newest", "pill-running"]);
335	  for (const [tag, target] of Object.entries(st.tags)) {
336	    if (target === v) out.push([tag, "pill-queued"]);
337	  }
338	  return out;
339	}
340	
341	function renderVersions(host, id, st, d, reload) {
342	  host.innerHTML = "";
343	  if (!st.versions.length) {
344	    host.innerHTML = `<div class="empty">No versions stored.</div>`;
345	    return;
346	  }
347	  for (const v of st.versions) {
348	    const row = document.createElement("div");
349	    row.className = "tpl-version" + (st.stable === v ? " tpl-version-live" : "");
350	    const pills = channelsFor(v, st)
351	      .map(([name, cls]) => `<span class="pill ${cls}">${escapeHtml(name)}</span>`)
352	      .join("");
353	    row.innerHTML = `
354	      <span class="tpl-vnum mono">v${v}</span>
355	      <span class="tpl-vchannels">${pills || `<span class="run-meta">no channel</span>`}</span>
356	      <select class="tpl-assign" title="point a channel at v${v}">
357	        <option value="">assign channel</option>
358	        ${ASSIGNABLE.map((c) => `<option value="${c}">${c}</option>`).join("")}
359	      </select>
360	      <button class="btn-ghost tpl-launch" ${st.stable === v ? "disabled" : ""}
361	        title="${st.stable === v ? "already live" : `make v${v} live for unpinned runs`}">Launch</button>
362	      <button class="btn-ghost tpl-view">Config</button>
363	      <button class="btn-ghost tpl-view-clean" title="comments stripped, canonical YAML">Clean</button>
364	      <button class="btn-danger tpl-del">Delete</button>
365	      <pre class="tpl-body" hidden></pre>`;
366	
367	    row.querySelector(".tpl-assign").onchange = async (ev) => {
368	      const tag = ev.target.value;
369	      if (!tag) return;
370	      try {
371	        await api(`/v1/templates/${encodeURIComponent(id)}/tags`, { method: "POST", body: { tag, version: v } });
372	        toast(`${tag} → v${v}`);
373	        reload();
374	      } catch (e) { toast(e.message, "error"); ev.target.value = ""; }
375	    };
376	
377	    row.querySelector(".tpl-launch").onclick = async () => {
378	      try {
379	        const r = await api(`/v1/templates/${encodeURIComponent(id)}/launch`, { method: "POST", body: { version: v } });
380	        toast(r.already_launched ? `v${r.version} was already live` : `v${r.version} is live${r.replaced != null ? ` (was v${r.replaced})` : ""}`);
381	        reload();
382	      } catch (e) { toast(e.message, "error"); }
383	    };
384	
385	    const body = row.querySelector(".tpl-body");
386	    // Config = raw stored body; Clean = comments stripped, canonical YAML (the
387	    // server renders it via ?clean=true, sharing the CLI's clean_config_yaml).
388	    // Each toggles the shared <pre>; switching modes refetches so the two views
389	    // never collide.
390	    const showConfig = async (clean) => {
391	      const mode = clean ? "clean" : "raw";
392	      if (!body.hidden && body.dataset.mode === mode) {
393	        body.hidden = true;
394	        return;
395	      }
396	      try {
397	        const q = clean ? `?version=${v}&clean=true` : `?version=${v}`;
398	        const rec = await api(`/v1/templates/${encodeURIComponent(id)}${q}`);
399	        body.textContent = rec.body;
400	        body.dataset.mode = mode;
401	        body.hidden = false;
402	      } catch (e) {
403	        toast(e.message, "error");
404	      }
