/* The graph scrolls both ways inside its card. The SVG keeps its natural pixel
   size (set as width/height attributes) rather than stretching to 100% — that
   is what lets wide labels overflow and scroll left/right instead of squashing. */
.lineage-graph { overflow: auto; background: var(--surface); border: 1px solid var(--border); border-radius: var(--r); padding: 8px; max-height: 78vh; }
.lineage-svg { display: block; }
.lineage-edge { fill: none; stroke: var(--border); stroke-width: 2; transition: stroke 0.15s, opacity 0.15s; }
.lineage-edge:hover { stroke: var(--brand-strong); }
.lineage-node rect { fill: var(--surface-2, #f4f6f8); stroke: var(--border); stroke-width: 1; transition: stroke 0.15s, fill 0.15s, opacity 0.15s; }
.lineage-node text { fill: var(--ink-dim); font-family: var(--font-mono); font-size: 11px; transition: fill 0.15s; }
.lineage-node:hover rect { stroke: var(--brand-strong); }
.lineage-root rect { stroke: var(--ok); stroke-width: 2.5; }
/* Click-to-highlight: the selected node, its neighbours, and their edges stay
   bright while everything else dims, so a dataset's connections read at a glance.
   Selected = solid brand; neighbour = brand tint; active edge = brand line. */
.lineage-node.is-selected rect { fill: var(--brand-strong); stroke: var(--brand-strong); }
.lineage-node.is-selected text { fill: #fff; }
.lineage-node.is-neighbour rect { fill: color-mix(in srgb, var(--brand-strong) 22%, var(--surface)); stroke: var(--brand-strong); }
.lineage-edge.is-active { stroke: var(--brand-strong); stroke-width: 2.5; }
.lineage-svg.has-selection .lineage-node:not(.is-selected):not(.is-neighbour) { opacity: 0.32; }
.lineage-svg.has-selection .lineage-edge:not(.is-active) { opacity: 0.18; }

