  background: var(--surface-2);
  color: var(--ink);
  border-color: var(--brand-strong);
  box-shadow: var(--shadow-1);
}
/* `display:block` above outranks the UA `[hidden]{display:none}` (same
   specificity, author wins), so the button stayed visible even when hidden was
   set. This restores it: at the end of the list the button truly disappears. */
.load-more[hidden] { display: none; }

